'use strict';
// Guides18: reusable route descriptions, explicit treasure states and opt-in help.
const Guides18={
 image:null,openImage:null,tutorialAllowed:false,
 trails:[
  {id:'archive',direction:'North ↑',region:'tideglass-archive',name:'The Tide Archive',path:'Scribe’s Cut',text:'Read the corrected date at the fork. Set the tide-wheel to release the chart-box’s latch. Salvage the coins and compass ring; bring the named keepsake to Rill.'},
  {id:'bond',direction:'East →',region:'brass-gully',next:'freed-quay',name:'The Cancelled Bond',path:'Brass Gully',text:'Meet Erelis, then continue north to Freed Quay. The receipt is a gift. Search the two branch seals and answer the second demand. The bell lift in Brass Gully is a separate small find.'},
  {id:'garden',direction:'West ←',region:'drowned-orchard',next:'lantern-garden',name:'The Garden Key',path:'Drowned Orchard',text:'Continue north into Lantern Garden. Find Neris’s key, return it, then help her send water to the common trough. A seed-tin also hides in the orchard’s low leaves.'}
 ],
 panel(title,body,buttons='',label='DIRECTIONS FOR THE ROAD'){show(`<h2 id="panel-title">${esc(title)}</h2>${body}<div class="actions">${buttons}<button data-action="close">${esc(returnPlaceLabel())}</button></div>`,'guides18',label);},
 button(action,label,id=''){return `<button data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;},
 status(id){if(id==='archive')return state.flags.includes('q16-keepsake-returned')?'Keepsake returned':Quest16.q().treasure.loot?'Salvage carried · return the keepsake':Quest16.q().treasure.sluice?'Chart-box unlocked':'Chart-box latched';const q=Treasure17.q()[id];return q.treasure?'Treasure carried':id==='bond'?(q.open?'Bridge open':q.receipt?'Receipt carried':'Meet Erelis'):(q.watered?'Water flowing':q.returned?'Key returned':q.key?'Key in your way-sack':'Find Neris’s key');},
 map(){
  const trails=this.trails.filter(t=>REGIONS[t.region]&&(!t.next||REGIONS[t.next]));
  const route=t=>`<div class="trail-map-stop"><strong>${esc(t.path)}</strong>${t.next?`<span>↑ ${esc(REGIONS[t.next].name.split(' · ')[0])}</span>`:'<span>Tide-wheel · chart-box</span>'}</div>`;
  this.panel('Tideglass · Three treasure trails',`<p>One ferry landing, <strong>three outward trails</strong>. Each can be followed on its own. The east and west trails each have a small salvage find on the way to a longer adventure. All return here; the southern ferry goes home to Reedbank.</p><div class="actions">${this.button('q17-journal','Detailed next steps')}</div><figure class="trail-map" aria-label="Route map: north to the Tide Archive, east to Brass Gully then north to Freed Quay, west to Drowned Orchard then north to Lantern Garden, south to the Reedbank ferry"><div class="trail-map-north">${route(trails.find(t=>t.id==='archive'))}<b>↑</b></div><div class="trail-map-cross">${route(trails.find(t=>t.id==='garden'))}<b>←</b><strong>Tideglass<br><small>You can return here</small></strong><b>→</b>${route(trails.find(t=>t.id==='bond'))}</div><div class="trail-map-south">↓<br>Ferry to Reedbank</div></figure>${trails.map(t=>`<section class="trail-summary"><h3>${esc(t.direction+' · '+t.name)}</h3><p>${esc(t.text)}</p><p class="hint">${esc(this.status(t.id))}</p></section>`).join('')}<p class="hint">Map of the currently open treasure trails. The battle boat and the long woodland quest leave from Reedbank, separately from this ferry.</p>`,'','RILL’S TRAIL BOARD');$('#panel').scrollTop=0;
 },
 rill(){const carried=state.items.includes('q16-sealed-keepsake'),done=state.flags.includes('q16-keepsake-returned');this.panel('Rill',`<p class="npc-role">Tide-marker · ferry guide and keeper of returned things</p><p>“Three trails; one landing to come home to. North is the old archive. East, Erelis keeps a cancelled bond. West, Neris tends a garden above the drowned orchard.”</p><p>“Coins and unmarked instruments are salvage. A sealed keepsake with somebody’s name still has a home.”</p>`,this.button('g18-map','Show me the treasure trails')+this.button('q16-keepsake',carried?'Show Rill the sealed keepsake':done?'Did the keepsake reach its owner?':'Ask about the sealed keepsake'),'A RIVER GUIDE');},
 keepsake(){const carried=state.items.includes('q16-sealed-keepsake'),done=state.flags.includes('q16-keepsake-returned');this.panel('The sealed keepsake',`<p>${done?'“The keeper’s family sent a blue thread back with the boat. It is home.” Rill loops the thread around an oarlock. “You kept your salvage and found the other thing its way.”':carried?'Rill turns the little case until a name catches the light. “I know that family. They moved upriver after the flood. I can take this to them—sealed, as you found it.”':'“A little sealed case was stored in the archive’s chart-box, north of the landing. A name is cut beside the hinge. If you find it, bring it here; you need not open it.”'}</p><p>${carried?'Your twelve silver pieces and compass ring remain yours. Giving the named case is a separate choice.':done?'The errand is complete. The case is no longer in your way-sack.':'Read the crossed-out date at this fork, then follow the north path under the arch. The tide-wheel releases the chest’s latch; there is no need to wade into the sea.'}</p>`,(carried?this.button('g18-return-keepsake','Give Rill the sealed keepsake'):'')+this.button('g18-map','Show the route on the trail board'),'A NAME BESIDE THE HINGE');},
 nessa(topic=''){
  const answers={
   battle:['Where is the battle boat?','“Down the western dock: the Thornwake boat. You land empty-handed. Gear is hidden in the bushes. Read the little sign on the island if you want fighting lessons. The ferry can bring you home whenever you choose.”'],
   quest:['Where does the long quest begin?','“Take the east boardwalk, then north along the bank into Woodland Road. Beyond the bridge, the Carvers need their beacon mended. The caravan at the woodland junction leads into Glasswind: giants, war camels, and a forge beyond the lost reaches. The lamp is made to carry a true pattern of light; someone has been changing its message.”'],
   treasure:['How do I find treasure?','“Rill’s ferry leaves from the middle dock, beside the festival. Tideglass has three trails: the tide archive north, the cancelled bond east, the garden key west. Read his trail board; all three bring you back to the same landing.”'],
   wisdom:['Where are the elves’ halls?','“Follow the bank into Woodland Road and cross the bridge. At the fork take the north road to Whiteledge. Sereth keeps the mountain records there. Beyond are the Carvers’ houses in the trees; Lethir knows the beacon craft. Take time to enter their homes and read their books.”']
  },a=answers[topic];
  this.panel('Aunt Nessa',`<p class="npc-role">Riverkin · lantern-keeper at Reedbank home</p><p>${a?esc(a[1]):'Nessa ties a fresh wick with blue thread. “For the wayfarers’ lantern. Take the bank road into Woodland, then cross the bridge to their camp. Or stay a moment. You have a question written all over your face.”'}</p>${a?`<p class="hint">${esc(a[0])}</p>`:'<p>“A battle, a long road, a treasure hunt, or a little time with the elves. Where would you like to begin? The Book is open by the door.”</p>'}`,
   Object.entries(answers).map(([id,[title]])=>this.button('g18-nessa',title,id)).join(''),'A WICK AND FOUR ROADS');
 },
 battleSign(){this.tutorialAllowed=true;this.panel('Thornwake · Read before the bell',`<p><strong>You arrive without a weapon.</strong> Search around the island: weapons lie hidden in low plants and among bushes. Walk close, then use <strong>X on a controller / E on a keyboard</strong> to examine a cache. Read and recall its Scripture headline to pick up the weapon. Reading pauses the fight.</p><p>Carry <strong>two weapons</strong>; Y / Q switches between them. Every sixth defeated attacker drops advanced gear somewhere on the field. Search where it fell; those caches need recall too.</p><p>Three lives, three waves. The bell gives only a few seconds before the attackers come. After twelve seconds without taking damage, battle health returns very slowly: one health over a minute of active play. The Heartwood crook’s power mends faster.</p><p>The return boat waits south. Start / Escape opens its menu.</p>`,this.button('g18-tutorial','Show me the simple fighting tutorial','0'),'THE ISLAND’S DIRECTION SIGN');},
 tutorial(page){if(!this.tutorialAllowed||state.region!=='thornwake')return;page=Math.max(0,Math.min(2,Number(page)||0));const steps=[['1 · Find and claim','Move with the left stick / D-pad, or WASD / arrows. Walk close to a bush. Press X / E to search. Read the passage and finish its short recall. You now hold a weapon. The fight waits while you read.'],['2 · Strike, then move','Press A / K to strike. Keep moving between swings. Heavy weapons take time to lift: begin their swing before an attacker reaches you. The right stick / mouse aims; close attacks help aim for you.'],['3 · Dodge and keep your distance','Press B / Space to dodge an orange warning. Hold LB / L to guard. Y / Q changes your two weapons. RB / R uses a special weapon power, or a charged burst. Start / Escape pauses. Try one control at a time.']][page];this.panel(steps[0],`<p>${esc(steps[1])}</p><p class="hint">${page+1} of 3 · reading this tutorial pauses the fight.</p>`,(page<2?this.button('g18-tutorial','Next',String(page+1)):'')+(page?this.button('g18-tutorial','Previous',String(page-1)):'')+this.button('g18-battle-sign','Back to the direction sign'),'SIMPLE FIGHTING TUTORIAL');},
 chest(x,y,h,opened){const im=opened?this.openImage:this.image;if(im?.complete&&im.naturalWidth){const H=h*(opened?1.35:1.24),W=h*1.24;ctx.drawImage(im,x-W/2,y-H*.95,W,H);}},
 seal(x,y,h,found){ctx.save();ctx.translate(x,y-h*.25);ctx.scale(h/50,h/50);ctx.fillStyle='#8f9b91';ctx.strokeStyle='#52685e';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,24,11,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle=found?'#f2d593':'#435d4e';ctx.beginPath();ctx.arc(0,-2,12,.4,5.8);ctx.moveTo(-7,3);ctx.lineTo(6,-7);ctx.moveTo(0,-2);ctx.lineTo(-6,-6);ctx.stroke();ctx.restore();},
 visit(id){if(id==='reedbank-aunt'){this.nessa();return true;}if(id==='q16-rill'){this.rill();return true;}if(id==='q16-hub-sign'||id==='q16-treasure-sign'){this.map();return true;}if(state.region==='thornwake'&&Leaf.sign(id)){this.battleSign();return true;}return false;},
 handle(action,id){if(action==='g18-map'){this.map();return true;}if(action==='g18-nessa'){this.nessa(id);return true;}if(action==='q16-keepsake'){this.keepsake();return true;}if(action==='g18-return-keepsake'){if(state.items.includes('q16-sealed-keepsake')){state.items=state.items.filter(i=>i!=='q16-sealed-keepsake');if(!state.flags.includes('q16-keepsake-returned'))state.flags.push('q16-keepsake-returned');persist();}this.keepsake();return true;}if(action==='g18-battle-sign'){if(this.tutorialAllowed)this.battleSign();return true;}if(action==='g18-tutorial'){this.tutorial(id);return true;}return false;},
 boot(){
  this.image=new Image();this.image.src='assets/guides18/closed-chest.032e9172aa9d.webp';this.openImage=new Image();this.openImage.src='assets/guides18/open-chest.992e6db7c983.webp';
  const places=visiblePlaces;visiblePlaces=()=>places().filter(p=>p.entry?.id!=='q17-key'||!Treasure17.q().garden.key&&!Treasure17.q().garden.returned&&!state.items.includes('q17-garden-key'));
  const visit=Leaf.visit;Leaf.visit=id=>this.visit(id)||visit.call(Leaf,id);
  const handle=Adventure.handle;Adventure.handle=(a,id)=>this.handle(a,id)||handle.call(Adventure,a,id);
  const journal=Treasure17.journal;Treasure17.journal=()=>{journal.call(Treasure17);const content=$('#panel-content');content.innerHTML=content.innerHTML.replace('Two trails from Tideglass','Treasure trail next steps');const actions=content.querySelector('.actions');if(actions)actions.insertAdjacentHTML?.('afterbegin',this.button('g18-map','Overview map · all three trails'));ensureMenuFocus();};
  const entities=Adventure.entities;Adventure.entities=()=>[...entities.call(Adventure),...(state.region==='tideglass-archive'?[{x:50,y:38,g18Kind:'tide-link'}]:[])];
  const draw=Adventure.drawEntity;Adventure.drawEntity=(p,x,y,h)=>{if(p.g18Kind==='tide-link'){const z=Math.max(viewZoom(),1.5/(canvas.width/canvas.height)),sy=canvas.width*z/150;ctx.save();ctx.strokeStyle=Quest16.q().treasure.sluice?'#d8ba6e':'#8b794f';ctx.lineWidth=Math.max(1.5,sy*.07);ctx.beginPath();ctx.moveTo(x+sy*.75,y);ctx.lineTo(x+sy*.75,y-15*sy);ctx.lineTo(x,y-15*sy);ctx.stroke();ctx.restore();return true;}const id=p.entry?.id;if(['q16-chart-box','q16-brass-box','q16-seed-tin'].includes(id)){if(id==='q16-seed-tin'&&TorCombat.distance(p,state.player)>5)return true;this.chest(x,y,h*.55,id==='q16-chart-box'?Quest16.q().treasure.loot:state.items.includes(id==='q16-brass-box'?'q16-bronze-bell':'q16-seed-tin'));return true;}return draw.call(Adventure,p,x,y,h);};
  const interact=Arena.interact;Arena.interact=()=>{const sign=OPENING_WORLD.regions[state.region]?.signs?.find(s=>{const p=OPENING_WORLD.regions[state.region].placements[s.id];return p&&TorCombat.distance(state.player,{x:p[0],y:p[1]})<3;});if(sign){this.battleSign();return;}interact.call(Arena);};
  const update=Arena.update;Arena.update=(...args)=>{update.apply(Arena,args);if(state.region==='thornwake'){const s=OPENING_WORLD.regions.thornwake.placements['leaf-boat-sign'];if(TorCombat.distance(state.player,{x:s[0],y:s[1]})<3){$('#nearby').textContent='X / E · Read the island direction sign';$('#interact').dataset.touchLabel='Read sign';}}};
 }
};
